lemma wsum_pos_of_esum_pos {μ : ℕ → ℝ} (hμ : ∀ n, 0 ≤ μ n) {V W : Finset ℕ}
    {E : Finset (ℕ × ℕ)} (hE : E ⊆ V ×ˢ W) (h : 0 < esum μ E) :
    0 < wsum μ V ∧ 0 < wsum μ W

theorem diagonal_recursion {p : Ultrafilter ℕ} (hp : Nonprincipal p) {A : Set ℕ}
    (h1 : A ∈ p + p) (h2 : A ∈ dbl p) :
    ∃ v : ℕ → ℕ, StrictMono v ∧ ∀ i j, i ≤ j → v i + v j ∈ A

theorem key_identity (b : ℕ → Bool) (hb : ¬ Owings b) {p : Ultrafilter ℕ}
    (hp : Nonprincipal p) :
    act (p + p) (encode (ext2 b)) = cmpl (act (dbl p) (encode (ext2 b)))

lemma alt_cauchy_schwarz {f g : ℝ → ℝ} (hf : Continuous f) (hg : Continuous g) {a b : ℝ}
    (hab : a ≤ b) :
    (∫ x in a..b, f x * g x) ^ 2 ≤ (∫ x in a..b, f x ^ 2) * (∫ x in a..b, g x ^ 2)

lemma alt_deriv_nonneg_of_convex {m m1 m2 : ℝ → ℝ} (hm : ∀ s, HasDerivAt m (m1 s) s)
    (hm1 : ∀ s, HasDerivAt m1 (m2 s) s) (hm2 : ∀ s, 0 ≤ m2 s) {B : ℝ}
    (hB : ∀ s ≤ 0, m s ≤ B) : ∀ s, 0 ≤ m1 s

theorem allWin_fam {Q : List ℕ → List ℕ → List ℕ → Prop} {pre per suf : Layers}
    (hper : 2 ≤ per.length) (h : AllWin Q (fam pre per suf 2)) (p : ℕ) :
    AllWin Q (fam pre per suf (p + 2))

theorem someWin_fam {Q : List ℕ → List ℕ → List ℕ → Prop} {pre per suf : Layers}
    (hper : per ≠ []) (h : SomeWin Q (fam pre per suf 2)) (p : ℕ) :
    SomeWin Q (fam pre per suf (p + 2))

lemma convex_incr_mono {s : Set ℝ} {F : ℝ → ℝ} (hF : ConvexOn ℝ s F) {u v h : ℝ}
    (hu : u ∈ s) (hv : v ∈ s) (huh : u + h ∈ s) (hvh : v + h ∈ s) (hh : 0 ≤ h) (huv : u ≤ v) :
    F (u + h) - F u ≤ F (v + h) - F v

theorem curve_sub_antitoneOn (hS : SepConfig D X) {c c' : E} (hcc : c 0 ≤ c' 0) :
    AntitoneOn (fun x => curve D c x - curve D c' x)
      {x | |x - c 0| < wid D ∧ |x - c' 0| < wid D}

lemma conc_nonneg_mid {I : Set ℝ} {G : ℝ → ℝ} (hG : ConcaveOn ℝ I G) {p q x : ℝ}
    (hp : p ∈ I) (hq : q ∈ I) (hpx : p < x) (hxq : x < q) (h1 : G p = 0) (h2 : G q = 0) :
    0 ≤ G x

lemma conc_nonpos_left {I : Set ℝ} {G : ℝ → ℝ} (hG : ConcaveOn ℝ I G) {p q x : ℝ}
    (hx : x ∈ I) (hq : q ∈ I) (hxp : x < p) (hpq : p < q) (h1 : G p = 0) (h2 : G q = 0) :
    G x ≤ 0

lemma conc_nonpos_right {I : Set ℝ} {G : ℝ → ℝ} (hG : ConcaveOn ℝ I G) {p q x : ℝ}
    (hp : p ∈ I) (hx : x ∈ I) (hpq : p < q) (hqx : q < x) (h1 : G p = 0) (h2 : G q = 0) :
    G x ≤ 0

lemma floor_le_of_block {A j : ℕ} (hj : j < A) {m : ℤ} {y y' : ℝ}
    (hy : (m : ℝ) ≤ 2 ^ A * y') (hy' : 2 ^ A * y < m + 1) :
    ⌊2 * (2 ^ j * y)⌋ ≤ ⌊2 * (2 ^ j * y')⌋
